-- Generated by Fuse. Holds `order_total` at its previous type (DOUBLE) while
-- consumers migrate to INT:
--   - order_history
--   - ORDER_HISTORY
--   - Customer Analytics Measures
--   - Essential KPI Measures
--   - Geographic Measures
--   - Product Perfromance Measures
--   ... and 6 more
--
-- The upstream value is already INT, so this cast cannot restore precision it
-- has lost. It exists only to keep the old column type available during the migration
-- window - delete the view once every consumer above reads INT directly.
-- Every column below was confirmed against DataHub at generation time.

select
    billing_address_id,
    cost_of_delivery,
    customer_id,
    delivery_address_id,
    delivery_type,
    order_date,
    order_id,
    order_mode,
    order_status,
    payment_method_code,
    promotion_id,
    sales_rep_id,
    wait_till_complete_yn,
    warehouse_id,
    cast(order_total as DOUBLE) as order_total
from {{ ref('orders') }}
